package com.example.dealership.customer;

import jakarta.validation.constraints.Email;
import jakarta.validation.constraints.NotBlank;
import jakarta.validation.constraints.Pattern;
import jakarta.validation.constraints.Size;

public record CustomerRequest(
        @NotBlank
        @Size(max = 100)
        String firstName,

        @NotBlank
        @Size(max = 100)
        String lastName,

        @NotBlank
        @Email
        @Size(max = 255)
        String email,

        @NotBlank
        @Size(max = 20)
        @Pattern(regexp = "\\+?[0-9 -]{6,20}", message = "must contain 6 to 20 digits, spaces or dashes, optionally starting with +")
        String phone,

        @Size(max = 10)
        @Pattern(regexp = "[0-9]{10}", message = "must be exactly 10 digits")
        String nip
) {
}

package com.example.dealership.customer;

public record CustomerResponse(
        Long id,
        String firstName,
        String lastName,
        String email,
        String phone,
        String nip
) {
}

package com.example.dealership.customer;

import java.util.Locale;

public final class CustomerMapper {

    private CustomerMapper() {
    }

    public static Customer toEntity(CustomerRequest request) {
        return new Customer(
                request.firstName(),
                request.lastName(),
                normalizeEmail(request.email()),
                request.phone(),
                request.nip());
    }

    public static void updateEntity(Customer customer, CustomerRequest request) {
        customer.setFirstName(request.firstName());
        customer.setLastName(request.lastName());
        customer.setEmail(normalizeEmail(request.email()));
        customer.setPhone(request.phone());
        customer.setNip(request.nip());
    }

    public static CustomerResponse toResponse(Customer customer) {
        return new CustomerResponse(
                customer.getId(),
                customer.getFirstName(),
                customer.getLastName(),
                customer.getEmail(),
                customer.getPhone(),
                customer.getNip());
    }

    static String normalizeEmail(String email) {
        return email.toLowerCase(Locale.ROOT);
    }
}

package com.example.dealership.customer;

import org.springframework.data.jpa.repository.JpaRepository;

public interface CustomerRepository extends JpaRepository<Customer, Long> {

    boolean existsByEmailIgnoreCase(String email);

    boolean existsByEmailIgnoreCaseAndIdNot(String email, Long id);
}

package com.example.dealership.customer;

import java.util.List;

import com.example.dealership.error.ConflictException;
import com.example.dealership.error.NotFoundException;

import org.springframework.data.domain.Sort;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

@Service
@Transactional(readOnly = true)
public class CustomerService {

    private final CustomerRepository customerRepository;

    public CustomerService(CustomerRepository customerRepository) {
        this.customerRepository = customerRepository;
    }

    public List<CustomerResponse> findAll() {
        return customerRepository.findAll(Sort.by("id")).stream()
                .map(CustomerMapper::toResponse)
                .toList();
    }

    public CustomerResponse findById(Long id) {
        return CustomerMapper.toResponse(getCustomer(id));
    }

    @Transactional
    public CustomerResponse create(CustomerRequest request) {
        if (customerRepository.existsByEmailIgnoreCase(request.email())) {
            throw emailAlreadyExists(request.email());
        }
        Customer customer = customerRepository.save(CustomerMapper.toEntity(request));
        return CustomerMapper.toResponse(customer);
    }

    @Transactional
    public CustomerResponse update(Long id, CustomerRequest request) {
        Customer customer = getCustomer(id);
        if (customerRepository.existsByEmailIgnoreCaseAndIdNot(request.email(), id)) {
            throw emailAlreadyExists(request.email());
        }
        CustomerMapper.updateEntity(customer, request);
        return CustomerMapper.toResponse(customerRepository.save(customer));
    }

    @Transactional
    public void delete(Long id) {
        customerRepository.delete(getCustomer(id));
    }

    private Customer getCustomer(Long id) {
        return customerRepository.findById(id)
                .orElseThrow(() -> new NotFoundException("Customer with id " + id + " not found"));
    }

    private static ConflictException emailAlreadyExists(String email) {
        return new ConflictException(
                "Customer with email " + CustomerMapper.normalizeEmail(email) + " already exists");
    }
}

