import org.springframework.test.web.servlet.MockMvc;

@WebMvcTest(CustomerController.class)
class CustomerControllerTest {

    private static final String EMAIL = "jan.kowalski@example.com";
    private static final String VALID_BODY = """
            {
              "firstName": "Jan",
              "lastName": "Kowalski",
              "email": "jan.kowalski@example.com",
              "phone": "+48 601 234 567",
              "nip": "5260250995"
            }
            """;

    @Autowired
    private MockMvc mockMvc;

    @MockitoBean
    private CustomerService customerService;

    @Test
    void findAllReturnsCustomers() throws Exception {
        when(customerService.findAll()).thenReturn(List.of(response()));

        mockMvc.perform(get("/api/customers"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.length()").value(1))
                .andExpect(jsonPath("$[0].id").value(1))
                .andExpect(jsonPath("$[0].email").value(EMAIL))
                .andExpect(jsonPath("$[0].phone").value("+48 601 234 567"))
                .andExpect(jsonPath("$[0].nip").value("5260250995"));
    }

    @Test
    void findByIdReturnsCustomer() throws Exception {
        when(customerService.findById(1L)).thenReturn(response());

        mockMvc.perform(get("/api/customers/1"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.email").value(EMAIL));
    }

    @Test
    void findByIdReturnsNotFoundProblemWhenCustomerDoesNotExist() throws Exception {
        when(customerService.findById(99L)).thenThrow(new NotFoundException("Customer with id 99 not found"));

        mockMvc.perform(get("/api/customers/99"))
                .andExpect(status().isNotFound())
                .andExpect(content().contentType(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.status").value(404))
                .andExpect(jsonPath("$.detail").value("Customer with id 99 not found"));
    }

    @Test
    void createReturnsCreatedCustomer() throws Exception {
        when(customerService.create(any(CustomerRequest.class))).thenReturn(response());

        mockMvc.perform(post("/api/customers").contentType(MediaType.APPLICATION_JSON).content(VALID_BODY))
                .andExpect(status().isCreated())
                .andExpect(header().string("Location", "http://localhost/api/customers/1"))
                .andExpect(jsonPath("$.id").value(1));
    }

    @Test
    void createAcceptsCustomerWithoutNip() throws Exception {
        String body = VALID_BODY.replace("\"5260250995\"", "null");
        when(customerService.create(any(CustomerRequest.class))).thenReturn(response());

        mockMvc.perform(post("/api/customers").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isCreated());
    }

    @Test
    void createReturnsBadRequestProblemWithFieldErrorsWhenRequestIsInvalid() throws Exception {
        mockMvc.perform(post("/api/customers").contentType(MediaType.APPLICATION_JSON).content(invalidBody()))
                .andExpect(status().isBadRequest())
                .andExpect(content().contentType(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.status").value(400))
                .andExpect(jsonPath("$.detail").value("Validation failed"))
                .andExpect(jsonPath("$.errors.length()").value(4))
                .andExpect(jsonPath("$.errors[0].field").value("email"))
                .andExpect(jsonPath("$.errors[0].message").value("must be a well-formed email address"))
                .andExpect(jsonPath("$.errors[1].field").value("lastName"))
                .andExpect(jsonPath("$.errors[1].message").value("must not be blank"))
                .andExpect(jsonPath("$.errors[2].field").value("nip"))
                .andExpect(jsonPath("$.errors[2].message").value("must be exactly 10 digits"))
                .andExpect(jsonPath("$.errors[3].field").value("phone"))
                .andExpect(jsonPath("$.errors[3].message")
                        .value("must contain 6 to 20 digits, spaces or dashes, optionally starting with +"));
        verifyNoInteractions(customerService);
    }

    @Test
    void createReturnsEnglishValidationMessagesWhenAcceptLanguageIsPolish() throws Exception {
        String body = VALID_BODY.replace("Kowalski\"", " \"");

        mockMvc.perform(post("/api/customers")
                        .header(HttpHeaders.ACCEPT_LANGUAGE, "pl")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content(body))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.errors.length()").value(1))
                .andExpect(jsonPath("$.errors[0].field").value("lastName"))
                .andExpect(jsonPath("$.errors[0].message").value("must not be blank"));
        verifyNoInteractions(customerService);
    }

    @Test
    void createReturnsBadRequestProblemWithFieldErrorWhenValueHasWrongType() throws Exception {
        String body = VALID_BODY.replace("\"Jan\"", "{}");

        mockMvc.perform(post("/api/customers").contentType(MediaType.APPLICATION_JSON).content(body))
                .andExpect(status().isBadRequest())
                .andExpect(jsonPath("$.errors.length()").value(1))
                .andExpect(jsonPath("$.errors[0].field").value("firstName"))
                .andExpect(jsonPath("$.errors[0].message").value("has an invalid value"));
        verifyNoInteractions(customerService);
    }

    @Test
    void createReturnsBadRequestProblemWhenBodyIsNotJson() throws Exception {
        mockMvc.perform(post("/api/customers").contentType(MediaType.APPLICATION_JSON).content("{ not json"))
                .andExpect(status().isBadRequest())
                .andExpect(content().contentType(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.detail").value("Validation failed"))
                .andExpect(jsonPath("$.errors.length()").value(1))
                .andExpect(jsonPath("$.errors[0].field").value(nullValue()))
                .andExpect(jsonPath("$.errors[0].message").value("request body must be valid JSON"));
        verifyNoInteractions(customerService);
    }

    @Test
    void createReturnsConflictProblemWhenEmailAlreadyExists() throws Exception {
        when(customerService.create(any(CustomerRequest.class)))
                .thenThrow(new ConflictException("Customer with email " + EMAIL + " already exists"));

        mockMvc.perform(post("/api/customers").contentType(MediaType.APPLICATION_JSON).content(VALID_BODY))
                .andExpect(status().isConflict())
                .andExpect(content().contentType(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.status").value(409))
                .andExpect(jsonPath("$.detail").value("Customer with email " + EMAIL + " already exists"));
    }

    @Test
    void createReturnsConflictProblemWhenDatabaseConstraintIsViolated() throws Exception {
        when(customerService.create(any(CustomerRequest.class)))
                .thenThrow(new DataIntegrityViolationException("uq_customer_email"));

        mockMvc.perform(post("/api/customers").contentType(MediaType.APPLICATION_JSON).content(VALID_BODY))
                .andExpect(status().isConflict())
                .andExpect(content().contentType(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.status").value(409))
                .andExpect(jsonPath("$.detail").value("Request conflicts with existing data"));
    }

    @Test
    void updateReturnsUpdatedCustomer() throws Exception {
        when(customerService.update(eq(1L), any(CustomerRequest.class))).thenReturn(response());

        mockMvc.perform(put("/api/customers/1").contentType(MediaType.APPLICATION_JSON).content(VALID_BODY))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.email").value(EMAIL));
    }

    @Test
    void updateReturnsNotFoundProblemWhenCustomerDoesNotExist() throws Exception {
        when(customerService.update(eq(99L), any(CustomerRequest.class)))
                .thenThrow(new NotFoundException("Customer with id 99 not found"));

        mockMvc.perform(put("/api/customers/99").contentType(MediaType.APPLICATION_JSON).content(VALID_BODY))
                .andExpect(status().isNotFound())
                .andExpect(content().contentType(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.status").value(404))
                .andExpect(jsonPath("$.detail").value("Customer with id 99 not found"));
    }

    @Test
    void updateReturnsBadRequestProblemWithFieldErrorsWhenRequestIsInvalid() throws Exception {
        mockMvc.perform(put("/api/customers/1").contentType(MediaType.APPLICATION_JSON).content(invalidBody()))
                .andExpect(status().isBadRequest())
                .andExpect(content().contentType(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.status").value(400))
                .andExpect(jsonPath("$.detail").value("Validation failed"))
                .andExpect(jsonPath("$.errors.length()").value(4))
                .andExpect(jsonPath("$.errors[0].field").value("email"))
                .andExpect(jsonPath("$.errors[1].field").value("lastName"))
                .andExpect(jsonPath("$.errors[2].field").value("nip"))
                .andExpect(jsonPath("$.errors[3].field").value("phone"));
        verifyNoInteractions(customerService);
    }

    @Test
    void updateReturnsConflictProblemWhenEmailAlreadyExists() throws Exception {
        when(customerService.update(eq(1L), any(CustomerRequest.class)))
                .thenThrow(new ConflictException("Customer with email " + EMAIL + " already exists"));

        mockMvc.perform(put("/api/customers/1").contentType(MediaType.APPLICATION_JSON).content(VALID_BODY))
                .andExpect(status().isConflict())
                .andExpect(content().contentType(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.status").value(409))
                .andExpect(jsonPath("$.detail").value("Customer with email " + EMAIL + " already exists"));
    }

    @Test
    void deleteReturnsNoContent() throws Exception {
        mockMvc.perform(delete("/api/customers/1"))
                .andExpect(status().isNoContent());

        verify(customerService).delete(1L);
    }

    @Test
    void deleteReturnsNotFoundProblemWhenCustomerDoesNotExist() throws Exception {
        doThrow(new NotFoundException("Customer with id 99 not found")).when(customerService).delete(99L);

        mockMvc.perform(delete("/api/customers/99"))
                .andExpect(status().isNotFound())
                .andExpect(content().contentType(MediaType.APPLICATION_PROBLEM_JSON))
                .andExpect(jsonPath("$.status").value(404))
                .andExpect(jsonPath("$.detail").value("Customer with id 99 not found"));
    }

    private static String invalidBody() {
        return """
                {
                  "firstName": "Jan",
                  "lastName": "",
                  "email": "not-an-email",
                  "phone": "phone",
                  "nip": "123"
                }
                """;
    }

    private static CustomerResponse response() {
        return new CustomerResponse(1L, "Jan", "Kowalski", EMAIL, "+48 601 234 567", "5260250995");
    }
}

package com.example.dealership.customer;

import static org.assertj.core.api.Assertions.assertThat;
import static org.assertj.core.api.Assertions.assertThatThrownBy;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

import java.util.List;
import java.util.Optional;

import com.example.dealership.error.ConflictException;
import com.example.dealership.error.NotFoundException;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.extension.ExtendWith;
import org.mockito.InjectMocks;
import org.mockito.Mock;
import org.mockito.junit.jupiter.MockitoExtension;
import org.springframework.data.domain.Sort;

@ExtendWith(MockitoExtension.class)
class CustomerServiceTest {

    private static final String EMAIL = "jan.kowalski@example.com";
    private static final String OTHER_EMAIL = "anna.nowak@example.com";

    @Mock
    private CustomerRepository customerRepository;

    @InjectMocks
    private CustomerService customerService;

    @Test
    void findAllReturnsMappedCustomers() {
        when(customerRepository.findAll(Sort.by("id"))).thenReturn(List.of(customer(EMAIL), customer(OTHER_EMAIL)));

        List<CustomerResponse> responses = customerService.findAll();

        assertThat(responses).extracting(CustomerResponse::email).containsExactly(EMAIL, OTHER_EMAIL);
    }

    @Test
    void findByIdThrowsNotFoundWhenCustomerDoesNotExist() {
        when(customerRepository.findById(99L)).thenReturn(Optional.empty());

        assertThatThrownBy(() -> customerService.findById(99L))
                .isInstanceOf(NotFoundException.class)
                .hasMessage("Customer with id 99 not found");
    }

    @Test
    void createSavesCustomer() {
        when(customerRepository.existsByEmailIgnoreCase(EMAIL)).thenReturn(false);
        when(customerRepository.save(any(Customer.class))).thenAnswer(invocation -> invocation.getArgument(0));

        CustomerResponse response = customerService.create(request(EMAIL));

        assertThat(response.firstName()).isEqualTo("Jan");
        assertThat(response.lastName()).isEqualTo("Kowalski");
        assertThat(response.email()).isEqualTo(EMAIL);
        assertThat(response.phone()).isEqualTo("+48 601 234 567");
        assertThat(response.nip()).isEqualTo("5260250995");
    }

    @Test
    void createSavesCustomerWithoutNip() {
        when(customerRepository.existsByEmailIgnoreCase(EMAIL)).thenReturn(false);
        when(customerRepository.save(any(Customer.class))).thenAnswer(invocation -> invocation.getArgument(0));

        CustomerResponse response = customerService.create(
                new CustomerRequest("Jan", "Kowalski", EMAIL, "+48 601 234 567", null));

        assertThat(response.nip()).isNull();
    }

    @Test
    void createStoresEmailInLowerCase() {
        when(customerRepository.existsByEmailIgnoreCase("Jan.Kowalski@Example.COM")).thenReturn(false);
        when(customerRepository.save(any(Customer.class))).thenAnswer(invocation -> invocation.getArgument(0));

        CustomerResponse response = customerService.create(request("Jan.Kowalski@Example.COM"));

        assertThat(response.email()).isEqualTo(EMAIL);
    }

    @Test
    void createThrowsConflictWhenEmailAlreadyExists() {
        when(customerRepository.existsByEmailIgnoreCase(EMAIL)).thenReturn(true);

        assertThatThrownBy(() -> customerService.create(request(EMAIL)))
                .isInstanceOf(ConflictException.class)
                .hasMessage("Customer with email " + EMAIL + " already exists");
        verify(customerRepository, never()).save(any());
    }

    @Test
    void createThrowsConflictWithNormalizedEmailWhenEmailDiffersOnlyInCase() {
        when(customerRepository.existsByEmailIgnoreCase("JAN.KOWALSKI@EXAMPLE.COM")).thenReturn(true);

        assertThatThrownBy(() -> customerService.create(request("JAN.KOWALSKI@EXAMPLE.COM")))
                .isInstanceOf(ConflictException.class)
                .hasMessage("Customer with email " + EMAIL + " already exists");
        verify(customerRepository, never()).save(any());
    }

    @Test
    void updateChangesExistingCustomer() {
        Customer customer = customer(EMAIL);
        when(customerRepository.findById(1L)).thenReturn(Optional.of(customer));
        when(customerRepository.existsByEmailIgnoreCaseAndIdNot(OTHER_EMAIL, 1L)).thenReturn(false);
        when(customerRepository.save(customer)).thenReturn(customer);

        CustomerResponse response = customerService.update(1L, request(OTHER_EMAIL));

        assertThat(response.email()).isEqualTo(OTHER_EMAIL);
        assertThat(customer.getEmail()).isEqualTo(OTHER_EMAIL);
        verify(customerRepository).save(customer);
    }

    @Test
    void updateStoresEmailInLowerCase() {
        Customer customer = customer(EMAIL);
        when(customerRepository.findById(1L)).thenReturn(Optional.of(customer));
        when(customerRepository.existsByEmailIgnoreCaseAndIdNot("Anna.Nowak@Example.com", 1L)).thenReturn(false);
        when(customerRepository.save(customer)).thenReturn(customer);

        customerService.update(1L, request("Anna.Nowak@Example.com"));

        assertThat(customer.getEmail()).isEqualTo(OTHER_EMAIL);
    }

    @Test
    void updateThrowsConflictWhenEmailBelongsToAnotherCustomer() {
        when(customerRepository.findById(1L)).thenReturn(Optional.of(customer(EMAIL)));
        when(customerRepository.existsByEmailIgnoreCaseAndIdNot(OTHER_EMAIL, 1L)).thenReturn(true);

        assertThatThrownBy(() -> customerService.update(1L, request(OTHER_EMAIL)))
                .isInstanceOf(ConflictException.class)
                .hasMessage("Customer with email " + OTHER_EMAIL + " already exists");
        verify(customerRepository, never()).save(any());
    }

    @Test
    void updateThrowsNotFoundWhenCustomerDoesNotExist() {
        when(customerRepository.findById(99L)).thenReturn(Optional.empty());

        assertThatThrownBy(() -> customerService.update(99L, request(EMAIL)))
                .isInstanceOf(NotFoundException.class)
                .hasMessage("Customer with id 99 not found");
    }

    @Test
    void deleteRemovesExistingCustomer() {
        Customer customer = customer(EMAIL);
        when(customerRepository.findById(1L)).thenReturn(Optional.of(customer));

        customerService.delete(1L);

        verify(customerRepository).delete(customer);
    }

    @Test
    void deleteThrowsNotFoundWhenCustomerDoesNotExist() {
        when(customerRepository.findById(99L)).thenReturn(Optional.empty());

        assertThatThrownBy(() -> customerService.delete(99L))
                .isInstanceOf(NotFoundException.class)
                .hasMessage("Customer with id 99 not found");
    }

    private static Customer customer(String email) {
        return new Customer("Jan", "Kowalski", email, "+48 601 234 567", "5260250995");
    }

    private static CustomerRequest request(String email) {
        return new CustomerRequest("Jan", "Kowalski", email, "+48 601 234 567", "5260250995");
    }
}

package com.example.dealership.customer;

import static org.assertj.core.api.Assertions.assertThat;

import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.orm.jpa.DataJpaTest;
import org.springframework.boot.test.autoconfigure.orm.jpa.TestEntityManager;

@DataJpaTest
class CustomerRepositoryTest {

    private static final String EMAIL = "ewa.zielinska@example.com";
    private static final String OTHER_EMAIL = "marek.lewandowski@example.com";

    @Autowired
    private CustomerRepository customerRepository;

    @Autowired
    private TestEntityManager entityManager;

    @Test
    void existsByEmailIgnoreCaseAndIdNotFindsEmailOfAnotherCustomer() {
        Customer first = customerRepository.save(
                new Customer("Ewa", "Zielińska", EMAIL, "600 100 200", null));
        Customer second = customerRepository.save(
                new Customer("Marek", "Lewandowski", OTHER_EMAIL, "600 100 300", "1234567890"));
        entityManager.flush();

        assertThat(customerRepository.existsByEmailIgnoreCaseAndIdNot(EMAIL, second.getId())).isTrue();
        assertThat(customerRepository.existsByEmailIgnoreCaseAndIdNot("Ewa.Zielinska@EXAMPLE.com", second.getId()))
                .isTrue();
        assertThat(customerRepository.existsByEmailIgnoreCaseAndIdNot(EMAIL, first.getId())).isFalse();
        assertThat(customerRepository.existsByEmailIgnoreCase("EWA.ZIELINSKA@example.com")).isTrue();
        assertThat(customerRepository.existsByEmailIgnoreCase("nobody@example.com")).isFalse();
    }

    @Test
    void saveStoresCustomerThatCanBeReadBack() {
        Customer saved = customerRepository.save(
                new Customer("Ewa", "Zielińska", EMAIL, "+48 600 100 200", "1234567890"));
        entityManager.flush();
        entityManager.clear();

        Customer found = customerRepository.findById(saved.getId()).orElseThrow();

        assertThat(found).isNotSameAs(saved);
        assertThat(found.getFirstName()).isEqualTo("Ewa");
        assertThat(found.getLastName()).isEqualTo("Zielińska");
        assertThat(found.getEmail()).isEqualTo(EMAIL);
        assertThat(found.getPhone()).isEqualTo("+48 600 100 200");
        assertThat(found.getNip()).isEqualTo("1234567890");
        assertThat(customerRepository.existsByEmailIgnoreCase(EMAIL)).isTrue();
        assertThat(customerRepository.existsByEmailIgnoreCaseAndIdNot(EMAIL, saved.getId())).isFalse();
    }
}

